#!/usr/bin/env python3
"""Validate AI config and compare generated files with a fresh sync (Python 3.11+)."""

import argparse
import json
from pathlib import Path
import shutil
import subprocess
import sys
import tempfile
import tomllib


ROOT = Path(__file__).resolve().parent.parent
HEADER = "GENERATED by scripts/sync-ai-config.py"
GENERATED_DIRS = (".agents/skills", ".agents/rules", ".codex/agents")


def require(condition, message):
    if not condition:
        raise ValueError(message)


def run_script(path, *args):
    result = subprocess.run(
        [sys.executable, "-X", "utf8", str(path), *map(str, args)],
        capture_output=True,
        text=True,
        encoding="utf-8",
    )
    require(result.returncode == 0, result.stderr or result.stdout)


def snapshot(root):
    files = {}
    for folder in GENERATED_DIRS:
        for path in (root / folder).rglob("*"):
            if path.is_file():
                files[path.relative_to(root).as_posix()] = path.read_bytes()
    return files


def validate(root):
    source = root / ".claude"
    require(source.is_dir(), f"Missing master config: {source}")
    json.loads((source / "settings.json").read_text(encoding="utf-8"))
    tomllib.loads((root / ".codex/config.toml").read_text(encoding="utf-8"))
    masters = list((source / "agents").glob("*.md"))
    agents = list((root / ".codex/agents").glob("*.toml"))
    require(len(masters) == len(agents) == 6, "Expected six source and generated agents")
    for path in agents:
        config = tomllib.loads(path.read_text(encoding="utf-8"))
        for key in ("name", "description", "developer_instructions"):
            require(bool(config.get(key)), f"{path}: missing {key}")
    for path in (source / "skills").iterdir():
        if path.is_dir():
            require((path / "SKILL.md").is_file(), f"Missing SKILL.md: {path}")
            require(
                (root / ".agents/skills" / path.name / "SKILL.md").is_file(),
                f"Missing copied skill: {path.name}",
            )
    command_names = set()
    for path in (source / "commands").rglob("*.md"):
        name = "-".join(path.relative_to(source / "commands").with_suffix("").parts)
        require(name not in command_names, f"Command names collide: {name}")
        require(not (source / "skills" / name).exists(), f"Command/skill collision: {name}")
        command_names.add(name)
        require(
            (root / ".agents/skills" / name / "SKILL.md").is_file(),
            f"Missing converted command: {name}",
        )
    for path in (root / ".agents/rules").glob("*.md"):
        text = path.read_text(encoding="utf-8")
        require(text.startswith("---\ntrigger: "), f"Missing trigger: {path}")

    # Regenerate in isolation; never rewrite the working project's config here.
    with tempfile.TemporaryDirectory(prefix="eco-agro-sync-") as folder:
        expected = Path(folder)
        shutil.copytree(source, expected / ".claude")
        shutil.copyfile(root / "CLAUDE.md", expected / "CLAUDE.md")
        (expected / "scripts").mkdir()
        sync = expected / "scripts/sync-ai-config.py"
        shutil.copyfile(root / "scripts/sync-ai-config.py", sync)
        run_script(sync)
        actual_files, expected_files = snapshot(root), snapshot(expected)
        differing = sorted(
            name for name in actual_files.keys() | expected_files.keys()
            if actual_files.get(name) != expected_files.get(name)
        )
        require(not differing, "Generated files out of sync: " + ", ".join(differing))
        actual_guidance = (root / "AGENTS.md").read_bytes()
        if HEADER.encode() in actual_guidance:
            require(actual_guidance == (expected / "AGENTS.md").read_bytes(), "AGENTS.md out of sync")
        else:
            print("NOTE: hand-written AGENTS.md is preserved; review its guidance separately.")
        manual = "# Hand-written guidance\nDo not overwrite.\n"
        (expected / "AGENTS.md").write_text(manual, encoding="utf-8")
        run_script(sync)
        require((expected / "AGENTS.md").read_text(encoding="utf-8") == manual,
                "Sync overwrote hand-written AGENTS.md")
    print(f"PASS: {root} — TOML, skills, commands, rules, sync parity and manual guidance protection")


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check-template", type=Path, help="Also scaffold and validate this template in a temporary folder")
    args = parser.parse_args()
    validate(ROOT)
    if args.check_template:
        with tempfile.TemporaryDirectory(prefix="eco-agro-scaffold-") as folder:
            target = Path(folder) / "project"
            run_script(args.check_template.resolve(), target, "--ten", "Eco Agro validation")
            run_script(target / "scripts/sync-ai-config.py")
            validate(target)
    return 0


if __name__ == "__main__":
    try:
        sys.exit(main())
    except (ValueError, OSError, tomllib.TOMLDecodeError) as error:
        print(f"FAIL: {error}", file=sys.stderr)
        sys.exit(1)
